metrics.workdir_dsl:
workspace "Parcel Tracker" "A parcel delivery tracking platform owned and operated by our company." {

    model {
        customer = person "Customer" "Uses the platform to look up the status of their parcels."

        emailProvider = softwareSystem "Email Delivery Provider" "An email delivery provider operated by a different organization, through which customer notification emails are sent." "External"

        parcelTracker = softwareSystem "Parcel Tracker" "A parcel delivery tracking platform owned and operated by our company." {
            webPortal = container "Web Portal" "A web portal where customers look up shipments. Embeds the shared pricing rules library, which computes delivery prices from weight and zone." "Web application"
            dispatchService = container "Dispatch Service" "A service that assigns parcels to couriers. Embeds the shared pricing rules library, which computes delivery prices from weight and zone." "Service"
            database = container "Database" "Stores shipments and dispatch records." "Database"

            customer -> webPortal "looks up the status of their parcels" "HTTPS/JSON"
            webPortal -> database "reads shipment records from" "SQL"
            dispatchService -> database "reads and writes dispatch records" "SQL"
            dispatchService -> emailProvider "sends customer notification emails" "REST/JSON"
        }
    }

    views {
        systemContext parcelTracker "SystemContext" "System context diagram for the Parcel Tracker." {
            include *
            autoLayout
        }

        container parcelTracker "Containers" "Container diagram for the Parcel Tracker." {
            include *
            autoLayout
        }
    }
}
